require_once __DIR__.'/../includes/functions.php';header('Content-Type: application/json; charset=utf-8');if($_SERVER['REQUEST_METHOD']!=='GET')json_out(['success'=>false,'message'=>'Método não permitido.'],405);$q=mb_substr(trim((string)($_GET['q']??'')),0,80);if(mb_strlen($q)<2)json_out(['success'=>true,'items'=>[]]);$like='%'.addcslashes($q,'%_\\').'%';$s=db()->prepare("SELECT p.id,p.name,p.price,p.unit,p.main_image FROM products p JOIN categories c ON c.id=p.category_id JOIN farmers f ON f.id=p.farmer_id WHERE p.status='active' AND c.is_active=1 AND (p.name LIKE ? OR c.name LIKE ? OR p.district LIKE ?) ORDER BY p.sales_count DESC LIMIT 8");$s->execute([$like,$like,$like]);$items=[];foreach($s as $p)$items[]=['id'=>$p['id'],'name'=>$p['name'],'price'=>money($p['price']),'image'=>get_product_image($p['main_image']),'url'=>base_path('produto.php?id='.$p['id'])];json_out(['success'=>true,'items'=>$items]);
